commands.stdout:
/dts-v1/;


/ {
 #address-cells = <2>;
 #size-cells = <2>;
 interrupt-parent = <&sysirq>;
 compatible = "mediatek,mt8163";
 aliases {
  aal0 = &aal;
  ccorr0 = &ccorr;
  color0 = &color;
  dither0 = &dither;
  dsi0 = &dsi;
  ovl0 = &ovl0;
  pwm0 = &pwm0;
  rdma0 = &rdma0;
 };
 cluster0_opp: opp-table-cluster0 {
  compatible = "operating-points-v2";
  opp-shared;
  opp-600000000 {
   opp-hz = /bits/ 64 <600000000>;
   opp-microvolt = <1150000>;
  };
  opp-624000000 {
   opp-hz = /bits/ 64 <624000000>;
   opp-microvolt = <1150000>;
  };
  opp-741000000 {
   opp-hz = /bits/ 64 <741000000>;
   opp-microvolt = <1150000>;
  };
  opp-871000000 {
   opp-hz = /bits/ 64 <871000000>;
   opp-microvolt = <1150000>;
  };
  opp-1050000000 {
   opp-hz = /bits/ 64 <1050000000>;
   opp-microvolt = <1150000>;
  };
  opp-1133000000 {
   opp-hz = /bits/ 64 <1133000000>;
   opp-microvolt = <1200000>;
  };
  opp-1216000000 {
   opp-hz = /bits/ 64 <1216000000>;
   opp-microvolt = <1250000>;
  };
  opp-1300000000 {
   opp-hz = /bits/ 64 <1300000000>;
   opp-microvolt = <1300000>;
  };
 };
 gpu_opp: opp-table-gpu {
  compatible = "operating-points-v2";
  opp-shared;
  opp-520000000 {
   opp-hz = /bits/ 64 <520000000>;
   opp-microvolt = <1150000>;
  };
  opp-416000000 {
   opp-hz = /bits/ 64 <416000000>;
   opp-microvolt = <1150000>;
  };
  opp-299000000 {
   opp-hz = /bits/ 64 <299000000>;
   opp-microvolt = <1150000>;
  };
 };
 vgpu_1v15: regulator-vgpu {
  compatible = "regulator-fixed";
  regulator-name = "vgpu-1v15";
  regulator-min-microvolt = <1150000>;
  regulator-max-microvolt = <1150000>;
  regulator-boot-on;
  regulator-always-on;
 };
 cpus {
  #address-cells = <1>;
  #size-cells = <0>;
  cpu0: cpu@0 {
   device_type = "cpu";
   compatible = "arm,cortex-a53";
   reg = <0x0>;
   enable-method = "psci";
   clocks = <&infracfg 71>,
     <&topckgen 81>;
   clock-names = "cpu", "intermediate";
   operating-points-v2 = <&cluster0_opp>;
   clock-frequency = <1300000000>;
   cci-control-port = <&cci_control2>;
   i-cache-size = <32768>;
   i-cache-line-size = <64>;
   i-cache-sets = <256>;
   d-cache-size = <32768>;
   d-cache-line-size = <64>;
   d-cache-sets = <128>;
   next-level-cache = <&l2_0>;
  };
  cpu1: cpu@1 {
   device_type = "cpu";
   compatible = "arm,cortex-a53";
   reg = <0x1>;
   enable-method = "psci";
   clocks = <&infracfg 71>,
     <&topckgen 81>;
   clock-names = "cpu", "intermediate";
   operating-points-v2 = <&cluster0_opp>;
   clock-frequency = <1300000000>;
   cci-control-port = <&cci_control2>;
   i-cache-size = <32768>;
   i-cache-line-size = <64>;
   i-cache-sets = <256>;
   d-cache-size = <32768>;
   d-cache-line-size = <64>;
   d-cache-sets = <128>;
   next-level-cache = <&l2_0>;
  };
  cpu2: cpu@2 {
   device_type = "cpu";
   compatible = "arm,cortex-a53";
   reg = <0x2>;
   enable-method = "psci";
   clocks = <&infracfg 71>,
     <&topckgen 81>;
   clock-names = "cpu", "intermediate";
   operating-points-v2 = <&cluster0_opp>;
   clock-frequency = <1300000000>;
   cci-control-port = <&cci_control2>;
   i-cache-size = <32768>;
   i-cache-line-size = <64>;
   i-cache-sets = <256>;
   d-cache-size = <32768>;
   d-cache-line-size = <64>;
   d-cache-sets = <128>;
   next-level-cache = <&l2_0>;
  };
  cpu3: cpu@3 {
   device_type = "cpu";
   compatible = "arm,cortex-a53";
   reg = <0x3>;
   enable-method = "psci";
   clocks = <&infracfg 71>,
     <&topckgen 81>;
   clock-names = "cpu", "intermediate";
   operating-points-v2 = <&cluster0_opp>;
   clock-frequency = <1300000000>;
   cci-control-port = <&cci_control2>;
   i-cache-size = <32768>;
   i-cache-line-size = <64>;
   i-cache-sets = <256>;
   d-cache-size = <32768>;
   d-cache-line-size = <64>;
   d-cache-sets = <128>;
   next-level-cache = <&l2_0>;
  };
  cpu-map {
   cluster0 {
    core0 {
     cpu = <&cpu0>;
    };
    core1 {
     cpu = <&cpu1>;
    };
    core2 {
     cpu = <&cpu2>;
    };
    core3 {
     cpu = <&cpu3>;
    };
   };
  };
  l2_0: l2-cache0 {
   compatible = "cache";
   cache-level = <2>;
   cache-size = <524288>;
   cache-line-size = <64>;
   cache-sets = <512>;
   cache-unified;
  };
 };
 psci {
  compatible = "arm,psci-0.2";
  method = "smc";
 };
 clocks {
  clk26m: oscillator-26m {
   compatible = "fixed-clock";
   #clock-cells = <0>;
   clock-frequency = <26000000>;
   clock-output-names = "clk26m";
  };
  clk32k: oscillator-32k {
   compatible = "fixed-clock";
   #clock-cells = <0>;
   clock-frequency = <32000>;
   clock-output-names = "clk32k";
  };
  system_clk: dummy13m {
   compatible = "fixed-clock";
   clock-frequency = <13000000>;
   #clock-cells = <0>;
  };
 };
 pmu {
  compatible = "arm,cortex-a53-pmu";
  interrupts = <0 8 8>,
       <0 9 8>,
       <0 10 8>,
       <0 11 8>;
  interrupt-affinity = <&cpu0>, <&cpu1>, <&cpu2>, <&cpu3>;
 };
 timer {
  compatible = "arm,armv8-timer";
  interrupt-parent = <&gic>;
  interrupts = <1 13 ((((1 << (4)) - 1) << 8) | 8)>,
       <1 14 ((((1 << (4)) - 1) << 8) | 8)>,
       <1 11 ((((1 << (4)) - 1) << 8) | 8)>,
       <1 10 ((((1 << (4)) - 1) << 8) | 8)>;
  clock-frequency = <13000000>;
  arm,no-tick-in-suspend;
 };
 soc {
  compatible = "simple-bus";
  #address-cells = <2>;
  #size-cells = <2>;
  ranges;
  topckgen: clock-controller@10000000 {
   compatible = "mediatek,mt8163-topckgen";
   reg = <0 0x10000000 0 0x1000>;
   #clock-cells = <1>;
  };
  infracfg: clock-controller@10001000 {
   compatible = "mediatek,mt8163-infracfg", "syscon";
   reg = <0 0x10001000 0 0x1000>;
   #clock-cells = <1>;
   #reset-cells = <1>;
  };
  syscfg_pctl_a: syscon@10005000 {
   compatible = "mediatek,mt8163-pctl-a-syscfg", "syscon";
   reg = <0 0x10005000 0 0x1000>;
  };
  scpsys: syscon@10006000 {
   compatible = "mediatek,mt8163-scpsys", "syscon", "simple-mfd";
   reg = <0 0x10006000 0 0x1000>;
   spm: power-controller {
    compatible = "mediatek,mt8163-power-controller";
    #address-cells = <1>;
    #size-cells = <0>;
    #power-domain-cells = <1>;
    power-domain@0 {
     reg = <0>;
     clocks = <&topckgen 51>;
     clock-names = "mm";
     #power-domain-cells = <0>;
     mediatek,infracfg = <&infracfg>;
    };
    power-domain@1 {
     reg = <1>;
     clocks = <&topckgen 51>;
     clock-names = "mm";
     #power-domain-cells = <0>;
    };
    power-domain@2 {
     reg = <2>;
     clocks = <&topckgen 51>;
     clock-names = "mm";
     #power-domain-cells = <0>;
    };
    power-domain@3 {
     reg = <3>;
     clocks = <&topckgen 51>;
     clock-names = "mm";
     #power-domain-cells = <0>;
    };
    power-domain@4 {
     reg = <4>;
     #power-domain-cells = <0>;
     mediatek,infracfg = <&infracfg>;
    };
    power-domain@5 {
     reg = <5>;
     #power-domain-cells = <0>;
    };
    power-domain@6 {
     reg = <6>;
     clocks = <&topckgen 54>;
     clock-names = "mfg";
     #address-cells = <1>;
     #size-cells = <0>;
     #power-domain-cells = <1>;
     mediatek,infracfg = <&infracfg>;
     power-domain@7 {
      reg = <7>;
      #power-domain-cells = <0>;
     };
    };
   };
  };
  watchdog: watchdog@10007000 {
   compatible = "mediatek,mt8163-wdt";
   reg = <0 0x10007000 0 0x1000>;
   interrupts = <0 128 8>;
   #reset-cells = <1>;
  };
  timer: timer@10008000 {
   compatible = "mediatek,mt8163-timer", "mediatek,mt6577-timer";
   reg = <0 0x10008000 0 0x1000>;
   interrupts = <0 152 8>;
   clocks = <&system_clk>, <&topckgen 80>;
   clock-names = "system-clk", "rtc-clk";
  };
  pio: pinctrl@1000b000 {
   compatible = "mediatek,mt8163-pinctrl";
   reg = <0 0x1000b000 0 0x1000>;
   mediatek,pctl-regmap = <&syscfg_pctl_a>;
   gpio-controller;
   #gpio-cells = <2>;
   interrupt-controller;
   #interrupt-cells = <2>;
   interrupts = <0 153 4>,
         <0 154 4>,
         <0 155 4>;
  };
  apmixedsys: clock-controller@1000c000 {
   compatible = "mediatek,mt8163-apmixedsys";
   reg = <0 0x1000c000 0 0x1000>;
   #clock-cells = <1>;
  };
  pwrap: pwrap@1000d000 {
   compatible = "mediatek,mt8163-pwrap";
   reg = <0 0x1000d000 0 0x1000>;
   reg-names = "pwrap";
   interrupts = <0 161 4>;
   resets = <&infracfg 13>;
   reset-names = "pwrap";
   clocks = <&topckgen 65>, <&infracfg 1>;
   clock-names = "spi", "wrap";
  };
  keypad: keyboard@10010000 {
   compatible = "mediatek,mt8163-keypad", "mediatek,mt6779-keypad";
   reg = <0 0x10010000 0 0x1000>;
   interrupts = <0 162 2>;
   clocks = <&clk26m>;
   clock-names = "kpd";
   status = "disabled";
  };
  sysirq: interrupt-controller@10200620 {
   compatible = "mediatek,mt8163-sysirq", "mediatek,mt6577-sysirq";
   reg = <0 0x10200620 0 0x20>;
   #interrupt-cells = <3>;
   interrupt-parent = <&gic>;
   interrupt-controller;
  };
  iommu: iommu@10205000 {
   compatible = "mediatek,mt8163-m4u";
   reg = <0 0x10205000 0 0x1000>;
   interrupts = <0 147 8>;
   mediatek,larbs = <&larb0 &larb1 &larb2 &larb3>;
   power-domains = <&spm 0>;
   #iommu-cells = <1>;
  };
  efuse: efuse@10206000 {
   compatible = "mediatek,mt8163-efuse", "mediatek,efuse";
   reg = <0 0x10206000 0 0x1000>;
   #address-cells = <1>;
   #size-cells = <1>;
   thermal_calibration: calib@100 {
    reg = <0x100 0xc>;
   };
  };
  rng@1020f000 {
   compatible = "mediatek,mt8163-rng", "mediatek,mt7623-rng";
   reg = <0 0x1020f000 0 0x1000>;
   clocks = <&infracfg 33>;
   clock-names = "rng";
  };
  gce: mailbox@10212000 {
   compatible = "mediatek,mt8163-gce", "mediatek,mt8173-gce";
   reg = <0 0x10212000 0 0x1000>;
   interrupts = <0 143 8>;
   clocks = <&infracfg 9>;
   clock-names = "gce";
   #mbox-cells = <2>;
  };
  mipi_tx0: dsi-phy@10215000 {
   compatible = "mediatek,mt8163-mipi-tx";
   reg = <0 0x10215000 0 0x1000>;
   clocks = <&apmixedsys 13>;
   clock-output-names = "mipi_tx0_pll";
   resets = <&infracfg 10>;
   #clock-cells = <0>;
   #phy-cells = <0>;
   status = "disabled";
  };
  gic: interrupt-controller@10221000 {
   compatible = "arm,gic-400";
   reg = <0 0x10221000 0 0x1000>,
         <0 0x10222000 0 0x1000>,
         <0 0x10224000 0 0x2000>,
         <0 0x10226000 0 0x2000>;
   interrupt-controller;
   #interrupt-cells = <3>;
   interrupt-parent = <&gic>;
   interrupts = <1 9 ((((1 << (4)) - 1) << 8) | 4)>;
  };
  cci: cci@10390000 {
   compatible = "arm,cci-400";
   #address-cells = <1>;
   #size-cells = <1>;
   reg = <0 0x10390000 0 0x1000>;
   ranges = <0 0 0x10390000 0x10000>;
   cci_control0: slave-if@1000 {
    compatible = "arm,cci-400-ctrl-if";
    interface-type = "ace-lite";
    reg = <0x1000 0x1000>;
   };
   cci_control1: slave-if@4000 {
    compatible = "arm,cci-400-ctrl-if";
    interface-type = "ace";
    reg = <0x4000 0x1000>;
   };
   cci_control2: slave-if@5000 {
    compatible = "arm,cci-400-ctrl-if";
    interface-type = "ace";
    reg = <0x5000 0x1000>;
   };
   pmu@9000 {
    compatible = "arm,cci-400-pmu,r1";
    reg = <0x9000 0x5000>;
    interrupts = <0 58 4>,
          <0 59 4>,
          <0 60 4>,
          <0 61 4>,
          <0 62 4>;
   };
  };
  auxadc: auxadc@11001000 {
   compatible = "mediatek,mt8163-auxadc", "mediatek,mt8173-auxadc";
   reg = <0 0x11001000 0 0x1000>;
   clocks = <&infracfg 34>;
   clock-names = "main";
   #io-channel-cells = <1>;
   status = "disabled";
  };
  apdma: dma-controller@11000300 {
   compatible = "mediatek,mt8163-uart-dma", "mediatek,mt6577-uart-dma";
   reg = <0 0x11000300 0 0x80>,
         <0 0x11000380 0 0x80>,
         <0 0x11000400 0 0x80>,
         <0 0x11000480 0 0x80>,
         <0 0x11000500 0 0x80>,
         <0 0x11000580 0 0x80>,
         <0 0x11000600 0 0x80>,
         <0 0x11000680 0 0x80>;
   interrupts = <0 102 8>,
         <0 103 8>,
         <0 104 8>,
         <0 105 8>,
         <0 106 8>,
         <0 107 8>,
         <0 108 8>,
         <0 109 8>;
   dma-requests = <8>;
   clocks = <&infracfg 42>;
   clock-names = "apdma";
   #dma-cells = <1>;
  };
  uart0: serial@11002000 {
   compatible = "mediatek,mt8163-uart", "mediatek,mt6577-uart";
   reg = <0 0x11002000 0 0x400>;
   interrupts = <0 91 8>;
   clocks = <&clk26m>, <&infracfg 19>;
   clock-names = "baud", "bus";
   dmas = <&apdma 0 &apdma 1>;
   dma-names = "tx", "rx";
   status = "disabled";
  };
  uart1: serial@11003000 {
   compatible = "mediatek,mt8163-uart", "mediatek,mt6577-uart";
   reg = <0 0x11003000 0 0x400>;
   interrupts = <0 92 8>;
   clocks = <&clk26m>, <&infracfg 20>;
   clock-names = "baud", "bus";
   dmas = <&apdma 2 &apdma 3>;
   dma-names = "tx", "rx";
   status = "disabled";
  };
  uart2: serial@11004000 {
   compatible = "mediatek,mt8163-uart", "mediatek,mt6577-uart";
   reg = <0 0x11004000 0 0x400>;
   interrupts = <0 93 8>;
   clocks = <&clk26m>, <&infracfg 21>;
   clock-names = "baud", "bus";
   dmas = <&apdma 4 &apdma 5>;
   dma-names = "tx", "rx";
   status = "disabled";
  };
  uart3: serial@11005000 {
   compatible = "mediatek,mt8163-uart", "mediatek,mt6577-uart";
   reg = <0 0x11005000 0 0x400>;
   interrupts = <0 94 8>;
   clocks = <&clk26m>, <&infracfg 22>;
   clock-names = "baud", "bus";
   dmas = <&apdma 6 &apdma 7>;
   dma-names = "tx", "rx";
   status = "disabled";
  };
  i2c0: i2c@11007000 {
   compatible = "mediatek,mt8163-i2c", "mediatek,mt8173-i2c";
   reg = <0 0x11007000 0 0x70>, <0 0x11000180 0 0x80>;
   interrupts = <0 84 8>;
   clock-div = <10>;
   clocks = <&infracfg 11>, <&infracfg 42>;
   clock-names = "main", "dma";
   #address-cells = <1>;
   #size-cells = <0>;
   status = "disabled";
  };
  i2c1: i2c@11008000 {
   compatible = "mediatek,mt8163-i2c", "mediatek,mt8173-i2c";
   reg = <0 0x11008000 0 0x70>, <0 0x11000200 0 0x80>;
   interrupts = <0 85 8>;
   clock-div = <10>;
   clocks = <&infracfg 12>, <&infracfg 42>;
   clock-names = "main", "dma";
   #address-cells = <1>;
   #size-cells = <0>;
   status = "disabled";
  };
  i2c2: i2c@11009000 {
   compatible = "mediatek,mt8163-i2c", "mediatek,mt8173-i2c";
   reg = <0 0x11009000 0 0x70>, <0 0x11000280 0 0x80>;
   interrupts = <0 86 8>;
   clock-div = <10>;
   clocks = <&infracfg 13>, <&infracfg 42>;
   clock-names = "main", "dma";
   #address-cells = <1>;
   #size-cells = <0>;
   status = "disabled";
  };
  spi: spi@1100a000 {
   compatible = "mediatek,mt8163-spi", "mediatek,mt2712-spi";
   reg = <0 0x1100a000 0 0x1000>;
   interrupts = <0 118 8>;
   clocks = <&topckgen 31>,
     <&topckgen 57>,
     <&infracfg 27>;
   clock-names = "parent-clk", "sel-clk", "spi-clk";
   assigned-clocks = <&infracfg 66>;
   assigned-clock-parents = <&topckgen 57>;
   #address-cells = <1>;
   #size-cells = <0>;
   status = "disabled";
  };
  thermal: thermal@1100b000 {
   #thermal-sensor-cells = <1>;
   compatible = "mediatek,mt8163-thermal";
   reg = <0 0x1100b000 0 0x1000>;
   interrupts = <0 78 8>;
   clocks = <&infracfg 10>, <&infracfg 34>;
   clock-names = "therm", "auxadc";
   resets = <&infracfg 0>;
   mediatek,auxadc = <&auxadc>;
   mediatek,apmixedsys = <&apmixedsys>;
   nvmem-cells = <&thermal_calibration>;
   nvmem-cell-names = "calibration-data";
  };
  usb0: usb@11200000 {
   compatible = "mediatek,mt8163-musb", "mediatek,mtk-musb";
   reg = <0 0x11200000 0 0x1000>;
   interrupts = <0 72 8>;
   interrupt-names = "mc";
   phys = <&u2port0 3>;
   dr_mode = "otg";
   clocks = <&infracfg 7>,
     <&infracfg 23>,
     <&apmixedsys 2>;
   clock-names = "main", "mcu", "univpll";
   status = "disabled";
  };
  u2phy0: t-phy@11210000 {
   compatible = "mediatek,mt8163-tphy", "mediatek,generic-tphy-v1";
   reg = <0 0x11210000 0 0x0800>;
   #address-cells = <2>;
   #size-cells = <2>;
   ranges;
   status = "disabled";
   u2port0: usb-phy@11210800 {
    reg = <0 0x11210800 0 0x0100>;
    clocks = <&apmixedsys 14>;
    clock-names = "ref";
    #phy-cells = <1>;
   };
   u2port1: usb-phy@11210900 {
    reg = <0 0x11210900 0 0x0100>;
    clocks = <&apmixedsys 14>;
    clock-names = "ref";
    #phy-cells = <1>;
   };
  };
  audiosys: clock-controller@11220000 {
   compatible = "mediatek,mt8163-audsys", "syscon";
   reg = <0 0x11220000 0 0x1000>;
   #clock-cells = <1>;
   afe: audio-controller {
    compatible = "mediatek,mt8163-afe-pcm";
    interrupts = <0 142 8>;
    power-domains = <&spm 5>;
    clocks = <&infracfg 49>,
      <&topckgen 63>,
      <&topckgen 64>,
      <&topckgen 71>,
      <&topckgen 72>,
      <&apmixedsys 8>,
      <&audiosys 6>,
      <&audiosys 13>,
      <&apmixedsys 9>,
      <&audiosys 5>,
      <&audiosys 14>,
      <&audiosys 0>,
      <&audiosys 9>,
      <&audiosys 10>,
      <&audiosys 11>,
      <&audiosys 2>,
      <&audiosys 3>,
      <&audiosys 1>,
      <&audiosys 15>,
      <&audiosys 16>,
      <&audiosys 17>,
      <&audiosys 18>,
      <&clk26m>;
    clock-names = "infrasys_aud",
           "top_pdn_aud",
           "top_pdn_aud_bus",
           "aud_1_sel",
           "aud_2_sel",
           "apll1",
           "apll1_tuner",
           "apll1_div",
           "apll2",
           "apll2_tuner",
           "apll2_div",
           "afe",
           "adc",
           "dac",
           "dac_predis",
           "22m",
           "24m",
           "top_i2s",
           "i2s0",
           "i2s1",
           "i2s2",
           "i2s3",
           "clk26m";
    status = "disabled";
   };
  };
  mmc0: mmc@11230000 {
   compatible = "mediatek,mt8163-mmc", "mediatek,mt2701-mmc";
   reg = <0 0x11230000 0 0x1000>;
   interrupts = <0 79 8>;
   clocks = <&infracfg 31>,
     <&topckgen 58>,
     <&infracfg 28>;
   clock-names = "source", "hclk", "bus_clk";
   status = "disabled";
  };
  mmc1: mmc@11240000 {
   compatible = "mediatek,mt8163-mmc", "mediatek,mt2701-mmc";
   reg = <0 0x11240000 0 0x1000>;
   interrupts = <0 80 8>;
   clocks = <&infracfg 29>,
     <&topckgen 59>;
   clock-names = "source", "hclk";
   status = "disabled";
  };
  mmc2: mmc@11250000 {
   compatible = "mediatek,mt8163-mmc", "mediatek,mt2701-mmc";
   reg = <0 0x11250000 0 0x1000>;
   interrupts = <0 81 8>;
   clocks = <&infracfg 30>,
     <&topckgen 60>;
   clock-names = "source", "hclk";
   status = "disabled";
  };
  usb1: usb@11270000 {
   compatible = "mediatek,mt8163-musb", "mediatek,mtk-musb";
   reg = <0 0x11270000 0 0x1000>;
   interrupts = <0 73 8>;
   interrupt-names = "mc";
